#include "stdafx.h"#include "Queue.h"#include "..\Lang.h"////~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~// Структураtypedef struct : public SPROLOZ  {  POINT pt;  } Queue_LineTo;//~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~// Функция отображенияint PaintLineTo(DefinePaint)  {  QueueP(Queue_LineTo);  ::LineTo( hDC, p->pt.x, p->pt.y );  return 1;  }//~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~void AddLineTo(DefineTegs)  {  POINT pt;  if ( !ParserPoint(teg[0].value,pt) ) return;  AddQueueEx(Queue_LineTo);  // Код, посылаемый в АРМ  p->btSendType = QUEUE_NO;  // Определение функции вывода  p->paint = &PaintLineTo;  //  p->pt = pt;  }//~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~